// ALPS: Adaptive Learned Perturbation Search — a task-agnostic metaheuristic for TSP, CVRP, FSSP
procedure ALPS(problem_instance, time_limit, params)
    elite_set ← empty_set; model ← InitializeMoveModel(problem_instance, params); start_time ← now();
    while now() - start_time < time_limit do
        s ← ConstructInitialSolution(problem_instance, model); s ← RepairIfNeeded(s, problem_instance);
        s ← LocalSearchWithAdaptiveMoves(s, model, problem_instance); record_best(elite_set, s);
        for iteration = 1 to params.max_perturb_iterations do
            s_pert ← Perturb(s, model, params); s_pert ← RepairIfNeeded(s_pert, problem_instance);
            s_pert ← LocalSearchWithAdaptiveMoves(s_pert, model, problem_instance);
            reward ← EvaluateReward(s, s_pert, problem_instance); UpdateMoveModel(model, s, s_pert, reward);
            s ← AcceptancePolicy(s, s_pert, model, params); record_best(elite_set, s);
        end for
        if StagnationDetected(elite_set, history) then
            s ← DiversifyFromElite(elite_set, model, problem_instance);
        end if
        model ← UpdateGlobalModel(model, elite_set, history, params); maintain_elite(elite_set, params.elite_size);
    end while
    return BestSolution(elite_set)
end procedure

// Notes on abstract components (task-agnostic):
// - ConstructInitialSolution: greedy, nearest-neighbor, or learned fragment assembly.
// - RepairIfNeeded: enforces problem-specific constraints (capacity for CVRP, precedence/order for FSSP, Hamiltonian tour for TSP).
// - LocalSearchWithAdaptiveMoves: repeatedly generate neighborhood moves, select using model (e.g., bandit/UCB or softmax), apply best feasible move, update local history.
// - Perturb: controlled destruction/reconstruction guided by model to escape local optima (remove k fragments, reinsert by learned heuristics).
// - UpdateMoveModel / UpdateGlobalModel: incrementally learn move and fragment values, track success rates to bias future selection (enables adaptivity across all three problem types).

